"1iuxptc": "{0} летают только на {1}. Выбери другую карту, чтобы лететь на другом кваде.",
"1bfwg4x": "Гонка, пилоты, общение, приглашения и настройки комнаты.",
"1tvwgf5": "Пилоты, общение, приглашения и настройки комнаты.",
"1f3jkpm": "Комната",
"1jg3mos": "{0} переносит комнату на {1}. Открой комнату, чтобы пойти следом или остаться. Промолчишь, и останешься.",
"h9h35p": "Ты переносишь комнату на {0}. Открой комнату, чтобы увидеть, кто идёт, или отмени.",
