"as2q8r": "Начать дрифт-раунд",
"1tcanqs": "Все снимают минуту баттлов, боты тоже. Или нажми G в полёте.",
"cencib": "Следующий можно начать, когда все дубли смонтированы.",
"1t3xzpa": "Каждый раунд запускает хост. Коза достаётся тому, кто последним затолкал её в гараж.",
"1uhhzk3": "Начать раунд с козами",
"q2xyhf": "Козы снова выходят, и все их загоняют, боты тоже. Или нажми G в полёте.",
"1v2b52g": "Сколько длится раунд, или пока все козы не окажутся дома. Меняется между раундами.",
"uh4xz1": "Любой",
"18w842j": "Матч идёт",
"14uj34k": "Каждый матч запускает хост. Оставайся белым и прячься или лови белых, когда станешь зелёным.",
"rnvxn9": "Начать матч",
"1q7cy0e": "Три раунда. Все на площадки, боты тоже. Или нажми G в полёте.",
"4rme3c": "Раунды идут друг за другом сами.",
"jrolc6": "Твои друзья и свободные места, и боты, чтобы их занять: лёгкие, средние или сложные. Боты летают с твоего компьютера и уступают место другу, который заходит.",
"1tip903": "Сколько длится охота. Меняется между матчами.",
"1h2plxw": "Сколько первый заражённый ждёт в баке.",
"tdpjp": "Кто начинает матч в стеклянном баке. Дальше следующий раунд начинает первый пойманный пилот.",
"cn1dzj": "Каждый матч запускает хост. Розовые против мятных: затолкай мяч в их ворота.",
