"gmcmay": "Лучший круг",
"c1wpf": "Сообщить о баге, оставить отзыв",
"192vw81": "F8 тоже открывает это.",
"ed56sy": "Escape тоже ставит на паузу.",
"ohwdis": "Музыка",
"1bxmxen": "Предыдущий трек",
"r6kxsl": "Выпустить коз",
"131g0xg": "Все козы снова на улице, таймер сброшен, можно загонять заново. Коза, которую ты уже видел, остаётся увиденной.",
"8bhfu8": "Призрак",
"1docbww": "На доске этой трассы уже есть",
"84b5uw": "Это значение не подходит.",
"hc0kdx": "Нужно имя.",
"aajo5": "Назови этот пресет",
"o0iip": "Имя пресета",
"zw419e": "Пресету нужно имя.",
"r5wqai": "Нет",
"17la1h6": "Пробел",
"j4kbpf": "Эта карта",
"1u3vyuq": "Выбери квад",
"9kgcci": "Лететь",
"1jh7nt4": "Настроить этот квад",
"wv167q": "Всегда летать здесь на {0}",
"10nopfd": "Поле зрения",
"unl4q1": "Шире видно больше, уже увеличивает. Узкий соответствует тому, что FPV-объектив делает с центром кадра; Стандарт возвращает часть этого ради ширины; Самый широкий это предел, на который эта картинка честно способна, и ворота будут казаться меньше.",
"4emmbg": "Рыбий глаз",
"1u80da4": "Изгибает картинку так, как это делает настоящий FPV-объектив: углы остаются там, куда их ставит поле зрения, края сжимаются, а центр становится крупнее. Выключено даёт прямую картинку без искажений. Если от широкого обзора укачивает, попробуй Слабый или Средний и возьми поле зрения пошире, чтобы вернуть ширину.",
"1ir4yll": "Угол камеры",
"6gsnw2": "Насколько камера наклонена вверх относительно рамы. {0} это ровно, взгляд вдоль носа. {1} это обычный круиз. От 45 до {2} это гонка. Выше примерно 30 рыскание начинает наклонять горизонт: при {3} градусах {4} процентов рыскания видны в кадре как крен. Так ведёт себя настоящая наклонённая камера. Чтобы это смягчить, снизь максимальную скорость рыскания на экране Рейты.",
"1vp9w8f": "Рыскание будет наклонять горизонт",
"1hjxoj1": "При наклоне {0} градусов {1} процентов рыскания видны в кадре как крен: {2} deg/s при твоей скорости рыскания {3} deg/s. Так ведёт себя настоящая наклонённая камера, и обычное решение в более медленном рыскании. Если снизить максимальную скорость рыскания до {4}, это вернётся к {5} deg/s. Изменить можно в любой момент на экране Рейты.",
"1f9wwkb": "Сохранить этот отчёт?",
"v5eaek": "Ты написал текст, который не отправлен. Черновики здесь не сохраняются, так что при закрытии он пропадёт.",
"13qi8go": "Отправить",
"ekjjsw": "Основа: собственные настройки Betaflight автора (изменено значений: {0}{1})",
"hqa4hr": "PID: как в комплекте настройки",
"i1tfp3": "Вес {0}%, Сцепление с воздухом {1}%, Мощность моторов {2}%",
"7x3x2g": "Батарея {0} В на банку, объектив {1} градусов, наклон {2}°",
"nnhdr0": "Она для {0}, поэтому ты перейдёшь на этот аппарат и его класс трасс.",
"1axqv1t": "Она меняет Сцепление с воздухом или Мощность моторов, поэтому включится Настройка ощущения полёта, а круг с ней пойдёт на общую доску с меткой Tuned.",
"t9yl6f": "Её настройки Betaflight заменят Твои правки на этом аппарате, пока ты не вернёшь свои.",
"f50exw": "Твои графика, стики, пульт и времена кругов не меняются.",
"1e5r0vj": "Эта сборка не может летать с этой настройкой. Возможно, она для аппарата, добавленного позже.",
"1os1q6k": "Эта настройка основана на настройке Betaflight, которой нет в этой сборке.",
"13lnrfy": "Этот браузер не смог сохранить настройку. Хранилище может быть заполнено или заблокировано.",
"ut38q5": "Не открылось. Проверь соединение и перезагрузи страницу.",
"1swhe85": "Музыка включена",
"1j851eb": "Музыка без звука",
"1bgesv6": "{0}. Нажми, чтобы включить звук.",
"1y9s6in": "{0}. Нажми, чтобы выключить звук.",
"19e4rfe": "Сообщить о баге",
"5bwmrs": "Достаточно заголовка и того, что случилось. Карта, графика, GPU и браузер уйдут вместе с тикетом, вводить их не нужно.",
"disqw2": "Просто хочешь рассказать, как он летает? Тогда оставь отзыв об ощущении полёта.",
