"l92ddx": "Правый большой палец",
"11li9o0": "Весь угол",
"653lk2": "Площадка больше, чем нарисовано: стик там, куда лёг палец в нижнем углу, а отклонение считается от этой точки.",
"c7cdxu": "Альбомная ориентация",
"1cau3o4": "Поверни телефон набок. Площадки окажутся под обоими большими пальцами, как пульт в двух руках.",
"b46ibj": "Черепаха",
"4uqxss": "Если окажешься на земле вверх ногами, появится подсказка TURTLE MODE. Дай тангаж или крен на правой площадке, чтобы перевернуться. Ловить момент не нужно. Отпусти и взлетай.",
"1qyunph": "Кнопка паузы справа вверху. От ударов отскакиваешь. Штраф измеряется временем. Продолжи, а если лежишь вверх ногами, дай тангаж или крен.",
"j3nmgx": "Лети в те, что пульсируют. Зелёная сторона для пролёта, красная сторона неправильная.",
"lkidd0": "Левый стик (Mode {0})",
"dgt1q3": "{0}. Режим задаётся на пульте, а эта страница подстраивается под него в настройках.",
"1a3en5u": "Переведи пульт в режим джойстика до загрузки этой страницы, затем запусти «Калибровку стиков» в настройках.",
"8pq8oh": "Тангаж двигает курсор, крен вправо выбирает, крен влево возвращает назад. После паузы или финиша подожди немного с отпущенными стиками и задержи крен на мгновение.",
"d45qj0": "Рестарт",
"ezjsbi": "R на клавиатуре или тумблер на пульте: Параметры, Тумблер рестарта, затем щёлкни им.",
"o7cl2g": "Если отпустить стики, квад держит то положение, в котором ты его оставил. Из каждого поворота нужно вылетать самому.",
"etorb5": "Если окажешься на земле вверх ногами, появится подсказка TURTLE MODE. Дай тангаж или крен правым стиком, чтобы перевернуться. Ловить момент не нужно. Верни стик в центр и взлетай.",
"1ri6cg": "Что это",
"14tfw5g": "Включить",
"1eqzli7": "Квад, Лаунч-контроль, Вкл. Пока не включишь сам, он выключен. Затем нажми L на стартовой линии, до того как добавлять газ.",
"14cfpm3": "Задать угол",
"11n5q78": "Газ на холостом. Наклоняй вперёд, пока OSD не покажет примерно 30 или 40 градусов. Верни стик в центр. Моторы удержат угол.",
"1aa3oyb": "Дай газ выше примерно 20 процентов. Удержание снимается, пропеллеры цепляют воздух, и ты летишь. После старта L сбрасывает его снова.",
"14arqvb": "Стрелка вверх даёт тангаж вперёд. W даёт газ. Лаунч-контроль на время удержания переключает тебя в Акро, а после старта возвращает твой режим.",
"r89zwp": "Та же последовательность, что на настоящей плате. L служит переключателем режима. Точнее настроить launch_angle_limit и launch_trigger_throttle_percent можно на Стенде прошивки, в разделе Квад.",
"1wrrqt3": "Если опрокинешься на старте, включится TURTLE MODE. Дай тангаж или крен, чтобы перевернуться. Ловить момент не нужно. Верни стик в центр, нажми L и стартуй снова.",
"1x7j2uc": "Лаунч-контроль, если ты включил его в разделе Квад. Наклон, центр, газ.",
"1xmpyfk": "Переключает Angle и Акро в полёте и запоминает выбор.",
"1eyul69": "R, затем Escape",
"1ns2uml": "Назад на стартовую линию и пауза.",
"1hg0wdz": "Если окажешься на земле вверх ногами, появится подсказка TURTLE MODE. Дай тангаж или крен стрелками, чтобы перевернуться. Ловить момент не нужно. Отпусти и взлетай.",
"19jaz7h": "Сообщить об ошибке или оставить отзыв. Если ты в воздухе, ставит паузу, затем открывает форму.",
"1ogqofk": "Площадки появляются в полёте, под большими пальцами.",
"1harh8g": "Подвигай стиками. Эти повторяют пульт.",
"149s8uu": "L взводит его. Наклон, центр, газ. Стики на экране по прежнему повторяют твои руки.",
"rt9bay": "Нажимай клавиши. Эти повторяют твои руки.",
"utog3i": "Сенсорные стики работают как настоящий пропорциональный стик, поэтому летают в том режиме полёта, что задан в разделе Квад: по умолчанию Акро, как на пульте. Angle мягче, пока учишься: отпусти правую площадку, и квад сам выровняется.",
"1uqyqut": "Аппаратура по умолчанию летает в Акро: стики задают скорость вращения, а отпущенные стики задают нулевую, и квад держит то положение, в котором находится. Сменить можно в пункте Режим полёта раздела Квад или клавишей M в полёте.",
"wtsp1v": "По умолчанию выключен, потому что газ с удержания получается резким и нужен не всем. Включи в разделе Квад, затем L на площадке. Зелёная надпись LAUNCH показывает угол тангажа. Она мигает, когда газ близок к срабатыванию.",
"t0ww0i": "Клавиша либо нажата, либо нет, поэтому аналогом служит время удержания: короткое нажатие чуть сдвигает стик, удержание держит удобное для полёта отклонение, долгое удержание доводит до упора. Гонки на клавишах начинаются в Angle, так что при отпускании квад выравнивается.",
"arpbtx": "На чём лететь",
"1k22ek3": "Без ворот, без кругов, две минуты",
"j7omzh": "Без ворот, без кругов, без часов",
"1pcy84h": "Рекорд трассы",
