"10gi4nt": "Рекорда пока нет",
"tkyf31": "Лучший круг по воротам",
"a6ppg": "Твой круг по воротам",
"r92sb6": "Чистый круг один, так что вот из чего он состоял. Пролети ещё один, и полоса покажет, где он потерял время.",
"2ba7i5": "Больше всего потеряно на {0}, {1} к твоему лучшему там.",
