"1y2w48a": "{1} пилота {0} с доски, ближайший круг быстрее твоего {2}, летит призраком рядом с тобой. Сразу на старт.",
"ocljwq": "Быстрее всех записанных кругов на доске. {1} пилота {0} стал призраком рекорда и летит рядом, держись впереди него.",
"dj5y8q": "Заезд окончен",
"iabifn": "В этом заезде нет чистого круга. Удар о землю или раму ворот стоит времени, которое уходит на то, чтобы снова разогнаться. Только ворота не по порядку аннулируют круг и возвращают тебя к мятному кольцу.",
"geyrsh": "Рекорд повторён",
