"1de3yfm": "Лучшее на этой карте",
"1k5dzyz": "Чистый заезд",
"kkya0r": "Ничего, что распознаватель смог бы назвать. Трюк означает полный оборот вокруг одной оси или круг вокруг чего-нибудь: флип, ролл, 360 по рысканию, powerloop под перилами. Поворот за угол трюком не считается и намеренно ничего не стоит.",
"1y2kek1": "Две минуты, и ничего, что распознаватель смог бы назвать. Трюк означает полный оборот вокруг одной оси или круг вокруг чего-нибудь: флип, ролл, 360 по рысканию, powerloop под перилами. Поворот за угол трюком не считается и намеренно ничего не стоит.",
"m2e6mk": "Ещё один вид трюков",
"1rjo3vh": "«Выложить этот заезд» отправляет на доску очки за трюки, {0}. Доска пока знает только трюки, поэтому гэпы, близкие пролёты и погоня в {1} считаются здесь, а не там.",
"1lipfcv": "Доска принимает только трюки, а в этом заезде не названо ни одного, так что выкладывать нечего. Гэпы, близкие пролёты и погоня в {0} считаются здесь.",
"nbri8l": "Угол камеры {0}°",
"1xqk8yk": "{0}: {1} {2}, слишком мало, чтобы летать.",
"182lfsh": "Нет ни пульта, ни геймпада.",
"1w5xlhk": "Выбери стик для {0}: нажми, затем отклони нужный стик.",
"bwl76q": "Подключён один джойстик",
"1chzf7k": "Нет джойстика",
"exl51q": "Нет джойстика, с которым эта страница может летать.",
"18qtwr8": "Нарисованные стики следуют твоей сохранённой калибровке.",
"pjwruo": "Нарисованные стики показывают, как страница читает его сейчас, и до калибровки это догадка. Если они не повторяют твои руки, всё равно выбери его и запусти «Калибровку стиков» в разделе {0}.",
"utpvx5": "Использовать этот?",
"1kepfr": "Двигается",
"1feqd8h": "В покое",
"10v17ee": "След стика",
"p9ydk8": "Сенсорные стики",
"1lrz4zo": "У пальца на стекле примерно четверть хода настоящего стика, и ничто не возвращает его в центр, поэтому числа ниже заданы мягче, чем значения по умолчанию для аппаратуры. Крен, тангаж и рыскание возвращаются, когда поднимаешь палец, а газ остаётся там, где ты его оставил, как на пульте.",
"iulg1q": "Клавиша не стик. При удержании стик плавно доходит до 34 процентов и остаётся там примерно три четверти секунды, а к секунде с четвертью дотягивается до упора. Поэтому рейты ниже рассчитаны на полёт с ПУЛЬТОМ: короткое нажатие даёт примерно треть от них, и поэтому полёт с клавиатуры ощущается жёстче и отзывается медленнее, чем говорят числа. Геймпад или пульт в режиме USB-джойстика получают всю кривую. А гонка на клавишах начинается в Angle, где эта кривая не действует: пункт «Гонки с клавиатуры» в разделе Квад или клавиша M в полёте переключают на Акро.",
"j83vdk": "Ждём сигнала от пульта. Подвигай стиком.",
"pc5ckr": "Аппаратура обновляется {0} раз в секунду. Betaflight в любом случае летает по фиксированной сетке кадров 250 Гц, так что это показывает, насколько свежее значение в каждом таком кадре.",
"tn3t15": "Это твоя частота кадров, {0} в секунду, то есть браузер читает пульт только раз за нарисованный кадр. Feedforward работает с ИЗМЕНЕНИЕМ между кадрами, поэтому стик, который шагает раз в кадр, ощущается как серия толчков, а не как одно движение. Рейты ниже этого не исправят.",
"1iahfwq": "Этот пульт передаёт около {0} шагов на полный ход стика, и на высоких рейтах такая грубость ощущается. Помогут пульт с более мелким шагом по USB или рейты пониже.",
