"1owx0ei": "Высоко, газ вниз, {pitch} полностью вперёд.",
"l71yrd": "Больше высоты, и лови газом, как только горизонт снова станет ровным.",
"cpwvzg": "Первый ролл",
"gwu4": "Один полный ролл в любую сторону, с большим запасом высоты под собой.",
"1enqsnv": "Ролл требует той же решимости, только на другой оси. Движение вперёд во время ролла не даёт кваду просесть.",
"1tiqtlm": "Лети вперёд, намного выше крыш.",
"7y4cbu": "Газ вниз, {roll} полностью в одну сторону и держи.",
"1rg0w5y": "Верни в центр, когда выровняешься, и добавь газ.",
"bao0ke": "Сначала высота.",
"17nz9pw": "Полный ролл",
