"v7623p": "Бэкфлип",
"1o1bp2n": "Полный флип назад, нос вверх и через себя.",
"6hf9fo": "Тот же флип в обратную сторону. Он ощущается иначе, потому что земля уходит за спину, а не вперёд.",
"1msymi2": "Набери хорошую высоту, выше крыш, и замедлись.",
"1cn67bw": "Газ вниз, {pitch} полностью на себя и держи.",
"4j69c5": "Поймай газом, когда вернётся горизонт.",
"sls0hq": "Бэкфлип",
