"167qo1q": "Одно комбо из трёх движений: гэпы, трюки или близкие пролёты, одно сразу за другим, чисто засчитанное.",
"17990ho": "Комбо состоит из движений, связанных с разницей в несколько секунд. Каждое держит его открытым, а засчитывается оно, когда ты останавливаешься. Связанные, они дают гораздо больше, чем те же движения по отдельности.",
