"7cukoz": "Из гэпа в трюк",
"1xwe34z": "Одно комбо, где связаны именной гэп и трюк: через гэп и сразу во флип, ролл или Powerloop.",
"f6tckd": "Из гэпа в трюк: вот фристайл-линия в одной фразе. Трюк нужно спланировать до гэпа, потому что после него думать некогда.",
"3gbvxn": "Выбери гэп, за которым открытый воздух: щит или пешеходный мост.",
"1864tje": "Через него, затем сразу в трюк.",
