"cyw1pe": "Браузерный симулятор FPV-гонок. Контроллер: Betaflight. Язык трасс взят из Track Draw. Остальное: один пилот и люди, которые летали, пока не стало как надо.",
"1sncokl": "Автор",
"kai17": "Построил этот симулятор, редактор и публичную доску. По пути дирижировал ордой из Grok и Claude.",
"1rju5ni": "Партнёры",
"10ax242": "Они поддерживают WebFPV.",
"1fpu7yw": "Бета-тестеры",
"2sef6d": "Они летали, пока он не стал ощущаться как квад.",
"lq4qk4": "Контроллер",
"152d3mr": "Рейты, PID-контур, фильтры, feedforward, TPA, iterm relax, airmode, anti-gravity. Скомпилированы в эту страницу, а не переписаны.",
"kfh8vm": "распространяется под GPLv3, значит, и это тоже. Экран полётного контроллера сделан как оммаж приложению",
"1ol0nlq": "10.10: названия вкладок, поля из 4.5.1 и классические тёмно-серый с оранжевым. Это не то приложение. Ни Vue, ни MSP, ни iframe. С благодарностью разработчикам Betaflight.",
"kwollz": "Язык трасс",
"91xq6y": "Редактор вдохновлён проектом",
"1v1kv66": ", от нидерландских богов дронов из",
"1ffizjn": "Комнаты RaceGOW5",
"ov7ihs": "Восемь трасс, шесть строителей, сняты с официальных анимаций.",
"f0ewtp": "Серия и анимации:",
"432t9y": "Орда",
"gw6sa5": "Написано с Grok. Построено с Claude.",
"1m26mn1": "Grok от xAI. Много строк, много споров и много упрямства насчёт ощущения полёта.",
"1i8y2kj": "Claude от Anthropic. Вторая половина орды. Стики держит всё тот же человек.",
"sskqzq": "Betaflight, Track Draw, Grok, Claude, Dutch Drone Squad и их знаки принадлежат их владельцам. Изображения каналов принадлежат пилотам. Их использование здесь означает благодарность, а не утверждение, что они одобряют эту страницу. Знаки партнёров принадлежат партнёрам и показаны с их согласия. WebFPV является свободным ПО под лицензией",
