"tyew7b": "{0}, уровень {1}.",
"1sdqly3": "Побеждает тот, кто лопнет больше квадов за три минуты.",
"17mggh1": "Побеждает тот, кто лопнет больше квадов за пять минут.",
"1xpgr9h": "Побеждает тот, кто первым лопнет десять квадов.",
"109vrui": "Без часов: сражайся, пока не уйдёшь.",
"p8yx1": "Сильные попадания: тебя лопают меньшим числом попаданий, и возвращения ждать дольше.",
"1dsfhgk": "Лопнул не значит выбыл: ты вернёшься через три секунды.",
"1l302t4": "Настрой:",
"1ra2hmr": "Попади в квад, чтобы снять ему здоровье. Когда оно кончается, он лопается, с конфетти. Каждый лопнувший квад даёт очко. Ракета идёт за квадом, как только рамка станет красной.",
"abeo2g": "В бой!",
"43eacj": "За каждым квадом тянется лента. Пролети сквозь чужую, чтобы обрезать её. Держи свою подальше от них. Обрезанная до конца лента исчезает, и её пилот тоже. Побеждает последняя лента.",
"1tj1cwp": "Летим!",
"11xt3fz": "Лети низко позади козы, и она побежит от тебя. Загони её в гараж Heads. Каждая коза принадлежит тому, кто загнал её последним, так что перехватывай у двери.",
"1xzga63": "Загоняй!",
"ckuwmm": "Выбери сторону, и боты займут все остальные места. Старт через секунды, никого ждать не нужно.",
"1t15mxw": "Мини-игра",
