"1g3lqvf": "Пульт или геймпад пока не доходит до этого браузера. Подключи его, переведи в режим джойстика и подвигай стиком: браузер показывает геймпад странице только после того, как на нём что-то сдвинется.",
"l55p9d": "Сохранённая калибровка читает {0} с оси, которой у этого геймпада нет, поэтому {1} ничего. У него есть {2}. Калибровать стики назначит всё заново по тому, что он реально отправляет.",
"10cte0": "Ось {0} движется как стик, и ничто в симуляторе её не читает. Браузер видит твой стик; в симуляторе он на неверном канале. Калибровать стики исправит это примерно за минуту.",
"13f86ul": "Ось {0} движется, и ничто в симуляторе её не читает. Если это и есть неработающий стик, Калибровать стики переведёт его на нужный канал.",
"3hxjne": "Это {0}, на оси {1}, и он доходит до симулятора.",
"4pid3q": "{0} двигался как стик, и ничто в симуляторе не читает {1}. Это стик на неверном канале, и Калибровать стики это исправит.",
"13inlwb": "Подвигай неработающим стиком до упора в каждую сторону и следи за полосками.",
"2niqw0": "На пульте: выбери режим USB-джойстика при подключении, до открытия этой страницы, и проверь выбранную на нём модель. Модель решает, что отправляет каждый канал, а новая или пустая может ничего не отправлять со стика.",
"jem3gg": "Твой пульт приходит как {0} осей.",
"rr1z7d": "Если ни одна полоска не движется: Windows",
"1j91r00": "Проверь, видит ли Windows стик: нажми Windows и R, введи joy.cpl, нажми Enter, выбери свой пульт и открой Свойства, затем подвигай им. Если там он движется, а здесь нет, сообщи о баге с этого экрана и напиши об этом.",
"1qj9g8y": "Если он не движется и там, значит, пульт его не передаёт. Калибровка в том окне Windows не меняет того, что читает браузер, так что она не нужна.",
"1elsn67": "Если ни одна полоска не движется: Mac",
"193sfmd": "В macOS нет своего теста стиков, так что тест и есть эти полоски. Если стик движется здесь в одном браузере и не движется в другом, сообщи о баге с этого экрана и напиши, в каком.",
"1lg87ci": "Если ни одна полоска не движется: Linux",
"fk484m": "jstest-gtk или evtest показывает, что передаёт пульт. Если стик движется там, а здесь нет, сообщи о баге с этого экрана и напиши об этом.",
"1ftvq9i": "Если ни одна полоска не движется",
"136r3g": "Ты пролетел уже {0} трасс.",
"1lxrdxg": "Это больше десяти минут фристайла.",
"mpbmvf": "Ещё два ползунка позволят попробовать собственные настройки.",
"1okdyz7": "Ещё один ползунок позволит попробовать собственные настройки.",
"wqsq97": "Хороший полёт",
"1piufrt": "Да, покажи",
"13g1wjf": "Нет, спасибо",
"106qgkp": "Скопировать код",
"k5t8v8": "Выдели и скопируй",
"1t5dr0c": "Забрать мою оценку",
"1k293vx": "Спасибо, оценка учтена.",
"f6vn3r": "Оценка отозвана.",
"nagz31": "Доска не смогла принять эту оценку.",
"9s1w1d": "От одной до пяти звёзд, по одной оценке от каждого. Её можно изменить или забрать. Пилоты видят среднее рядом с названием, и доска может ставить лучшее первым.",
"fi2r1e": "Поделиться этой настройкой",
"d8h2dl": "Выкладывает настройку, на которой ты летаешь, на публичную доску с коротким кодом, который любой может вставить, чтобы полетать на ней. Отправляется вот это, и только это:",
"86leg4": "Не входит: твоя графика, стики и пульт, режим полёта и время кругов. Загрузка настройки никогда их не трогает.",
"1fdzjrk": "Назови эту настройку",
"69ns7i": "Спокойная и цепкая",
"5slhk5": "Пара слов о ней (необязательно)",
"152173s": "Для чего она хороша, что попробовать сначала.",
"1g2zpqe": "Пара слов о ней",
"zsv2pw": "Показывается как автор",
"m2bcgo": "Поделиться",
"1pm6ttj": "Дай ей название, от трёх символов.",
"1idobjn": "Отправка",
"1t7t2wk": "Опубликовано",
"1tg83oy": "Она на доске. Отправь этот код тому, кто хочет на ней полетать.",
"1ic5sf9": "Посмотреть на доске",
"zg560k": "Доска не смогла принять эту настройку.",
"oi32d0": "Загрузить настройку",
"1wgb6n": "Вставь код, например k7mq-2xrt-9vwd. Ты увидишь, что в настройке, до того как что-либо изменится, и сможешь вернуть свою.",
"5gnh65": "Код настройки",
