"1lszfx8": "Zip для другой программы и для сборки по нему: трасса в виде данных, страница с инструкцией, карта, виды комнаты и анимация круга",
"1pbhrck": "Админ",
"nk9zpp": "Войти как админ доски, чтобы отмечать трассы официальными и править официальные",
