"iz6qh4": "Сумерки",
"1ti6h5c": "Пасмурно",
"1kq6380": "Золотой час: низкое тёплое солнце и длинные фиолетовые тени. Собственный свет города.",
"r0wxsi": "Высокое белое солнце, короткие резкие тени и густо-синее небо.",
"ige15v": "Солнце на горизонте и фиолетовое небо. Зажигаются окна, фонари, рекламные щиты и торговые автоматы.",
"1dpyzgh": "Ровный серо-фиолетовый день с мягкими тенями и близкой дымкой.",
