"1cr7f7k": "Грунт",
"wnpobs": "Двор из пиленых бетонных плит с жёлтой линией по краю.",
"yi1f2h": "Тёмная парковка, с разметкой мест и стрелками вокруг всего, что ты ставишь.",
"1a197nq": "Газон внутри бордюра. На нём не рисуются линии, кроме стартовой зоны.",
"5uugym": "Двор из утрамбованной земли со следами шин.",
