"q0b6ur": "{0}. Щёлкни, чтобы посмотреть, тяни, чтобы двигать, Delete убирает из круга.",
"47t10a": "Порядок пролёта: щёлкай по деталям в том порядке, в каком летишь",
"l5kyq0": "Порядок пролёта (N). Щёлкай по деталям в том порядке, в каком летишь: повторный щелчок по детали добавляет ещё один проход через неё.",
"1l304es": "Объекты",
"1n9g4h1": "Твёрдые тела",
"1j8s2pg": "Предупреждения",
"1s93bks": "Размер участка, сетка, время суток и покрытие",
