"92kvsy": "Очистить порядок пролёта и начать его заново, вместе с путевыми точками. Одна отмена возвращает его",
"1cfa0q1": "Страница для печати: где стоит каждая деталь, с размерами от угла, и какие трубы и фитинги купить",
