"seajwm": "Закрыть панель с порядком пролёта, предупреждениями и профилем. Esc",
"1l4fpy8": "Над барьером пролетают.",
"5ozvlp": "Порядок пролёта: нажми на следующую деталь. Та же деталь ещё раз добавляет ещё один проход.{0} Нажми на плюс ещё раз, чтобы убрать инструмент.",
"1fj7bqd": "Порядок пролёта: щёлкни по следующей детали. Та же деталь ещё раз добавляет ещё один проход.{0} Backspace убирает последний проход. Esc убирает инструмент.",
"16bob4g": "Порядок пролёта: щёлкни по первой детали, через которую идёт круг, затем по следующей. Та же деталь ещё раз добавляет ещё один проход.{0} Esc убирает инструмент.",
"1h3i156": "Нажми на пол, чтобы поставить куб: пять ворот одной деталью, которые пролетают прямо насквозь, туда, куда он смотрит. Инструмент остаётся выбранным. Нажми Куб ещё раз, чтобы убрать его.",
"jihh0f": "Щёлкни по полу, чтобы поставить куб: пять ворот одной деталью, которые пролетают прямо насквозь, туда, куда он смотрит. Инструмент остаётся выбранным. Правый щелчок или Esc убирает его.",
"1hjaiqs": "Убери его через Инструменты.",
"947ub9": "Нажми на него ещё раз слева, чтобы убрать.",
"ret7py": "Тяни по полу, чтобы поставить ряд из двух или трёх ворот, через 30 in. Один щелчок ставит пару. Правый щелчок или Esc убирает инструмент.",
"p956s2": "Щёлкни по двум точкам, чтобы измерить расстояние между ними. Щелчок рядом с воротами или шестом берёт их середину. Правый щелчок или Esc убирает линейку.",
"6y6p5i": "Щёлкни по двум точкам, чтобы измерить расстояние между ними, в метрах. Щелчок рядом с деталью берёт её середину. Правый щелчок или Esc убирает линейку.",
"na57ja": "Тяни по земле от пролёта, который пролетается первым, чтобы поставить стену. Одно нажатие ставит три пролёта. Одна стена, затем инструмент убирается.",
"1x41sn8": "Тяни по земле от пролёта, который пролетается первым, чтобы поставить стену из ворот с общими стойками, от двух до шести. Один щелчок ставит трое. Одна стена, затем инструмент убирается. Alt поворачивает её свободно.",
"3qzdj6": "Нажми",
"m8sun": "Щёлкни",
"lzc7fh": "Формы находятся в Инструментах.",
"ybq1cu": "{0} там, где встанут стартовые ворота вверх: горизонтальные ворота на высоте 15 ft, которые пролетают вверх снизу, с подъёмом и перевалом для их пролёта в виде путевых точек. Одни ворота, затем инструмент убирается.",
"36gz3q": "{0} там, где встанет барьер-перекладина: перекладина шириной 10 ft на высоте 5 ft на двух ножках, повёрнутая поперёк трассы, и круг проходит над ней. Пролёт под ней или впритирку задаётся на карточке. Один барьер, затем инструмент убирается.",
"1onrj1y": "{0} там, где встанет барьер: щит длиной 4 м и высотой 1 м с флагом на каждом конце, повёрнутый поперёк трассы, и круг проходит над ним. Один барьер, затем инструмент убирается.",
"1cwij39": "{0} там, где встанут ворота вверх: наклон 45 градусов, нижний край на высоте 1,5 м, пролетаются снизу вверх. Одни ворота, затем инструмент убирается.",
"18zqy2o": "Щёлкни на {0}, чтобы поставить. Инструмент остаётся выбранным, так что второй щелчок ставит ещё. Правый щелчок или Esc убирает его.",
"gtzrzu": "Тяни, чтобы двигать. Тяни кольцо у основания, чтобы повернуть.",
"11yaxra": "Тяни, чтобы двигать. Тяни кольцо у основания, чтобы повернуть. Стрелки сдвигают понемногу.",
"1k9grnp": "В Инструментах есть детали, чтобы поставить ещё.",
"1weh0ir": "Выбери инструмент слева, чтобы поставить ещё.",
"dmd4gm": "Щёлкни по воротам, чтобы выбрать их. Нажми на {0} в пустом месте и тяни, чтобы осмотреться. Выбери инструмент слева, чтобы поставить ещё.",
"13ytpyk": "Правый щелчок или Esc убирает его.",
"1sj82o4": "Правый щелчок или Esc убирает линейку.",
"gy64hi": "Машина ездит по дороге, а на этой карте дорог пока нет. Сначала проложи дорогу инструментом Дорога.",
"1wq4lkk": "Щёлкни по детали, чтобы выбрать её. Тяни, чтобы двигать, а кольцо у основания поворачивает её. Тяни за пустую землю, чтобы осмотреться. Выбери инструмент слева, чтобы поставить ещё.",
"1hid29q": "Открой Инструменты и выбери: {0}, затем нажми на {1}.",
"102rg1e": "Или начни с готовой трассы RaceGOW и передвинь ворота.",
"90n8s5": "Начать с трассы RaceGOW",
