"vmluuy": "Или начни с трассы с доски и сделай её своей. Прямой угол на панели держит новые ворота по сторонам света, как чертится план.",
"4d31w9": "Трассы для пятидюймовых из раздела Карты и трассы, каждая открывается как твоя копия",
"gdyprl": "В порядке пролёта пока ничего нет. Поставь ворота, и они появятся здесь, вместе с показателями круга и предупреждениями.",
