"hwn39s": "Самый крутой поворот",
"s659t5": "Сообщать не о чем. Линия проходит через каждый элемент в правильном направлении, внутри поля, не задевая преград.",
"1jtc0ud": "Предупреждения носят рекомендательный характер. Ничто здесь не мешает сохранению или экспорту.",
