"908nna": "На участке",
"15pazei": "Сообщать не о чем. Каждый промежуток между двумя объектами закрыт или достаточно широк для пролёта, старт свободен, и каждый именной гэп открыт.",
"zwg152": "Дорога: щёлкни, чтобы поставить её первый узел",
