"1248f0f": "Машина: щёлкни по дороге",
"18fby00": "Набор сел-шейдинга не загрузился ({0}), поэтому 3D-вид рисует каждый объект простыми твёрдыми телами. Карта не затронута.",
"hrcfdw": "3D-вид не смог загрузить объекты для фристайла ({0}), поэтому показывает участок без них. 2D-вид не затронут.",
"ak6mu4": "Номер {0}, один из проходов через эту деталь (всего {1}). Щёлкни, чтобы посмотреть, дважды щёлкни, чтобы дать другое место.",
"1l6mpsh": "Номер {0} в порядке пролёта. Щёлкни, чтобы посмотреть, дважды щёлкни, чтобы дать другое место.",
