"td7316": "В порядке пролёта пока ничего нет. Поставь элемент, и он войдёт в порядок автоматически.",
"scsh3n": "Стартовых площадок нет. Линия идёт от первого элемента до последнего, и круг не замыкается. Нажми S, чтобы поставить их.",
"91vn4y": "Объект по-прежнему построен и твёрдый.",
"hmu6f5": "{0}: буква слишком мала для своей трубы. От просвета, через который её пролетают, ничего не остаётся, когда вокруг него идёт труба, так что там нечего засчитывать. Увеличь букву.",
"1xhn5ud": "{0}: просвет в самом широком месте всего {1} м против 1,5 м у стандартных ворот, так что кваду там тесно. Если так задумано трассой, не обращай внимания; иначе увеличь букву.",
