"1f6an1h": "{0}: объект стоит за пределами поля.",
"up72l1": "{0} и {1} стоят в одном месте, поэтому у линии между ними нет направления.",
"1fgg8vv": "{0}: объект смотрит в сторону от {1}. Линия уходит от него задом наперёд. Нажми X, чтобы развернуть сторону.",
